export const USGS_DEM_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/usgs-dem-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getUsgsDemStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(USGS_DEM_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
